import { Component, createEffect, on, onCleanup, Show, useContext } from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { GameActionName } from "#core/ui-next/services/actionButtons.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";

export interface HotkeyDefinition {
	hotkeyAction: GameActionName;
	onActivate?: () => void;
	navTrayText?: string;
	disabled?: boolean;
}

export interface HotkeyProps {
	hotkeys: HotkeyDefinition[];
}

const HotkeysComponent: Component<HotkeyProps> = (props) => {
	const context = useContext(HotkeyContext);

	createEffect(
		on(
			() => props.hotkeys,
			(hotkeys, prevHotkeys) => {
				for (const hotkey of prevHotkeys ?? []) {
					context.unregisterHotkey(hotkey.hotkeyAction);
					if (hotkey.navTrayText) {
						context.unregisterNavtray(hotkey.hotkeyAction);
					}
				}

				for (const hotkey of hotkeys) {
					if (!hotkey.disabled) {
						context.registerHotkey(hotkey.hotkeyAction, hotkey.onActivate ?? (() => null));
						if (hotkey.navTrayText) {
							context.registerNavtray(hotkey.hotkeyAction, hotkey.navTrayText);
						}
					}
				}
			},
		),
	);

	onCleanup(() => {
		for (const hotkey of props.hotkeys) {
			context.unregisterHotkey(hotkey.hotkeyAction);
			if (hotkey.navTrayText) {
				context.unregisterNavtray(hotkey.hotkeyAction);
			}
		}
	});

	return null;
};

export const Hotkeys = ComponentRegistry.register("HotkeysComponent", HotkeysComponent);

export interface InlineHotkeyProps extends HotkeyDefinition {
	class?: string;
}

const InlineHotkeyComponent: Component<InlineHotkeyProps> = (props: InlineHotkeyProps) => {
	return (
		<Show when={IsControllerActive()}>
			<Activatable
				hotkeyAction={props.hotkeyAction}
				navTrayText={props.navTrayText}
				onActivate={props.onActivate}
				disabled={props.disabled}
				disableFocus={true}
				class={props.class}
			>
				<NavHelp />
			</Activatable>
		</Show>
	);
};

export const InlineHotkey = ComponentRegistry.register("InlineHotkey", InlineHotkeyComponent);
